bounded_host_request.command:
set -eu
docker exec -i debug-ai-debug-ai-1 node - <<'NODE'
const fs=require("node:fs"),path=require("node:path"),{decodeEnvelope}=require("/app/orchestrator/durable-primitives.js"),{contentHash}=require("/app/orchestrator/durable-contracts.js"),{RuntimeEvidenceStore}=require("/app/server/runtime-evidence.js");
const rid="run_mwyrd8e8_1f1203c5ab",base="/app/runtime/durable/durable";
const store=new RuntimeEvidenceStore("/app/runtime");
const rows=store.list(rid,{types:["deterministic_verification","dap_hint","execution_failure","stage_reuse"],limit:100});
for(const r of rows){const p=r.payload;if(r.type==="deterministic_verification")console.log("REPRO",r.created_at,contentHash(p),JSON.stringify(p.checks.map(c=>({status:c.status,executed:c.executed,check_type:c.check_type,timed_out:c.timed_out,backend:c.sandbox?.backend,network:c.sandbox?.network,hash:contentHash(c)}))));else if(r.type==="dap_hint")console.log("DAP",r.created_at,contentHash(p),p.status,p.reason);else console.log(r.type,r.created_at,JSON.stringify({code:p.code,stage:p.stage,role:p.role}));}
const dir=path.join(base,"workflow-data",rid);
for(const f of fs.readdirSync(dir).filter(x=>/^wd_.*\.json$/.test(x))){const r=decodeEnvelope(fs.readFileSync(path.join(dir,f)),{expectedSchema:"workflow-data/v1"});if(r.kind==="STAGE_RESULT")console.log("STAGE",r.refs?.stage,r.payload?.saved_at,r.payload?.reuse_binding);}
const w=path.join(base,"work-item",rid);
for(const d of fs.readdirSync(w))for(const f of fs.readdirSync(path.join(w,d))){const r=decodeEnvelope(fs.readFileSync(path.join(w,d,f)),{expectedSchema:"role-work-item-continuation/v1"});console.log("CHECKPOINT",r.key,r.steps,r.status,r.input_binding);}
NODE
